294	// ---- reading the cluster ----------------------------------------------------
295	
296	// observation is what one round read: the pods of Nexus and its claim.
297	type observation struct {
298		pods []podObject
299		pvc  *claimObject
300	}
301	
302	type podObject struct {
303		Metadata struct {
304			Name              string  `json:"name"`
305			DeletionTimestamp *string `json:"deletionTimestamp"`
306		} `json:"metadata"`
307		Status struct {
308			Phase      string `json:"phase"`
309			Conditions []struct {
310				Type    string `json:"type"`
311				Status  string `json:"status"`
312				Reason  string `json:"reason"`
313				Message string `json:"message"`
314			} `json:"conditions"`
315			ContainerStatuses []containerStatus `json:"containerStatuses"`
316		} `json:"status"`
317	}
318	
319	type containerStatus struct {
320		Ready        bool `json:"ready"`
321		RestartCount int  `json:"restartCount"`
322		State        struct {
323			Waiting    *struct{ Reason string } `json:"waiting"`
324			Running    *struct{}                `json:"running"`
325			Terminated *struct{ Reason string } `json:"terminated"`
326		} `json:"state"`
327		LastState struct {
328			Terminated *struct{ Reason string } `json:"terminated"`
329		} `json:"lastState"`
330	}
331	
332	type claimObject struct {
333		Metadata struct {
334			Name string `json:"name"`
335		} `json:"metadata"`
336		Status struct {
337			Phase string `json:"phase"`
338		} `json:"status"`
339	}
340	
341	// observe reads the pods of Nexus and the claims of the namespace.
342	func (d *deployer) observe(ctx context.Context) (observation, error) {
343		var obs observation
344		ns := d.pf.p.Namespace
345		var pods struct {
346			Items []podObject `json:"items"`
347		}
348		if err := d.read(ctx, "read the Nexus pod", []string{"get", "pods", "-n", ns, "-l", podSelector, "-o", "json"}, &pods); err != nil {
349			return obs, err
350		}
351		var claims struct {
352			Items []claimObject `json:"items"`
353		}
354		if err := d.read(ctx, "read the volume claim", []string{"get", "pvc", "-n", ns, "-o", "json"}, &claims); err != nil {
355			return obs, err
356		}
357		obs.pods = pods.Items
358		if len(claims.Items) > 0 {
359			obs.pvc = &claims.Items[0]
360		}
361		return obs, nil
362	}
363	
364	// read runs a read-only kubectl call and decodes its JSON answer into into.
365	func (d *deployer) read(ctx context.Context, what string, args []string, into any) error {
366		out, errOut, err := d.pf.remote(ctx, args...)
367		if err != nil {
368			if cerr := ctx.Err(); cerr != nil {
369				return cerr
370			}
371			return d.pf.failure("could not "+what, args, string(errOut), err)
372		}
373		if err := json.Unmarshal([]byte(out), into); err != nil {
374			return &BenchError{
375				Kind:  Unclassified,
376				Cause: "kubectl answered with something that is not the answer to \"" + what + "\"",
377				Check: d.pf.command(args...),
378				Err:   err,
379			}
380		}
381		return nil
382	}
383	
384	// describe is the one-line state of the round, for the progress and the deadline.
385	func (o observation) describe() string {
386		var parts []string
387		if len(o.pods) == 0 {
388			parts = append(parts, "no pod matches "+podSelector+" yet")
389		}
390		for _, pod := range o.pods {
391			parts = append(parts, pod.describe())
392		}
393		if o.pvc == nil {
394			parts = append(parts, "no volume claim yet")
395		} else {
396			parts = append(parts, fmt.Sprintf("claim %s is %s", o.pvc.Metadata.Name, o.pvc.Status.Phase))
397		}
398		return strings.Join(parts, "; ")
399	}
400	
401	func (pod podObject) describe() string {
402		s := fmt.Sprintf("pod %s: phase %s", pod.Metadata.Name, pod.Status.Phase)
403		if len(pod.Status.ContainerStatuses) == 0 {
404			if _, ok := pod.unschedulable(); ok {
405				return s + ", cannot be scheduled"
406			}
407			return s + ", not started"
408		}
409		cs := pod.Status.ContainerStatuses[0]
410		switch {
411		case cs.State.Waiting != nil:
412			return s + ", container waiting (" + cs.State.Waiting.Reason + ")"
413		case cs.State.Running != nil && cs.Ready:
414			return s + ", container running and ready"
415		case cs.State.Running != nil:
416			return s + ", container running, not ready"
417		}
418		return s + ", container not running"
419	}
420	
421	// ---- diagnosis --------------------------------------------------------------
422	
423	// diagnose reads a round. failure is a state that ends the wait at once;
424	// pending is a state that does (when it lasts) but may also be passing.
425	func diagnose(p Params, obs observation) (failure, pending *BenchError) {
426		for _, pod := range obs.pods {
427			if pod.Metadata.DeletionTimestamp != nil {
428				continue
429			}
430			if f := podFailure(p, pod); f != nil {
431				return f, nil
432			}
433		}
434		return nil, pendingReading(p, obs)
435	}
436	
437	// podFailure is a pull that fails or a container that crashes.
438	func podFailure(p Params, pod podObject) *BenchError {
439		for _, cs := range pod.Status.ContainerStatuses {
440			waiting := ""
441			if cs.State.Waiting != nil {
442				waiting = cs.State.Waiting.Reason
443			}
444			last := ""
445			healthy := cs.Ready && cs.State.Running != nil
446			switch {
447			case healthy:
448				// An old termination stays in lastState while the pod lives: a
449				// container that runs and is ready again is not crashing.
450			case cs.LastState.Terminated != nil:
451				last = cs.LastState.Terminated.Reason
452			case cs.State.Terminated != nil:
453				last = cs.State.Terminated.Reason
454			}
455			switch {
456			case waiting == reasonErrImagePull || waiting == reasonImagePullBackOff:
457				return &BenchError{
458					Kind:  ImagePull,
459					Cause: fmt.Sprintf("the image %s could not be pulled (%s)", p.ImageRef(), waiting),
460					Check: describePodCommand(p) + ", then check " + envImage + ", " + envImageTag + " and the access of the cluster to the registry",
461				}
462			case waiting == reasonCrashLoop || last == reasonOOMKilled:
463				return crashFailure(p, waiting, last)
464			}
465		}
466		return nil
467	}
468	
469	func crashFailure(p Params, waiting, last string) *BenchError {
470		state := "restarted"
471		if waiting != "" {
472			state = waiting
473		}
474		if last == "" {
475			last = "unknown"
476		}
477		return &BenchError{
478			Kind:  Crash,
479			Cause: fmt.Sprintf("the Nexus container keeps crashing (%s, last termination: %s) with a memory limit of %s", state, last, p.MemoryLimit),
480			Check: describePodCommand(p) + " and `kubectl --context " + p.Context + " -n " + p.Namespace + " logs deploy/nexus --previous`; raise " + envMemoryLimit + " when it was " + reasonOOMKilled,
481		}
482	}
483	
484	// pendingReading is a pod that cannot be scheduled, or a claim that stays
485	// Pending although a pod is scheduled. The pod comes first: while it is not
486	// scheduled, a claim of a WaitForFirstConsumer class is Pending for that reason
487	// alone.
488	func pendingReading(p Params, obs observation) *BenchError {
489		scheduled := false
490		for _, pod := range obs.pods {
491			if pod.Metadata.DeletionTimestamp != nil {
492				continue
493			}
494			if msg, ok := pod.unschedulable(); ok {
495				return unschedulableReading(p, msg)
496			}
497			scheduled = scheduled || pod.scheduled()
498		}
499		if scheduled && obs.pvc != nil && obs.pvc.Status.Phase == "Pending" {
500			return &BenchError{
501				Kind:  PodPending,
502				Cause: fmt.Sprintf("the volume claim %s (%s of storage) is still Pending although the pod is scheduled", obs.pvc.Metadata.Name, p.StorageSize),
503				Check: kubectlIn(p, "describe", "pvc", obs.pvc.Metadata.Name) + ", then lower " + envStorageSize + " or check the default StorageClass",
504			}
505		}
506		return nil
507	}
508	
509	func unschedulableReading(p Params, msg string) *BenchError {
510		var lacks, envs []string
511		if strings.Contains(msg, "Insufficient memory") {
512			lacks = append(lacks, "memory (requested "+p.MemoryRequest+")")
513			envs = append(envs, envMemoryRequest)
514		}
515		if strings.Contains(msg, "Insufficient cpu") {
516			lacks = append(lacks, "cpu (requested "+p.CPURequest+")")
517			envs = append(envs, envCPURequest)
518		}
519		be := &BenchError{Kind: PodPending, Cause: "the Nexus pod cannot be scheduled", Check: describePodCommand(p)}
520		if len(lacks) > 0 {
521			be.Cause += ": the node has not enough " + strings.Join(lacks, " and ") + " left"
522			be.Check += ", then lower " + strings.Join(envs, " or ")
523		}
524		return be
525	}
526	
527	// scheduled reports whether the PodScheduled condition is True.
528	func (pod podObject) scheduled() bool {
529		for _, c := range pod.Status.Conditions {
530			if c.Type == "PodScheduled" && c.Status == "True" {
531				return true
532			}
533		}
534		return false
535	}
536	
537	// unschedulable returns the message of the Unschedulable PodScheduled=False
538	// condition, and whether the pod has one.
539	func (pod podObject) unschedulable() (message string, ok bool) {
540		for _, c := range pod.Status.Conditions {
541			if c.Type == "PodScheduled" && c.Status == "False" && c.Reason == "Unschedulable" {
542				return c.Message, true
543			}
544		}
545		return "", false
546	}
547	
548	// describePodCommand is the kubectl command that describes the Nexus pod.
549	func describePodCommand(p Params) string {
550		return kubectlIn(p, "describe", "pod", "-l", podSelector)
551	}
552	
553	// kubectlIn is a kubectl command line, in the namespace of the bench, a user can
554	// run to repeat a diagnosis.
555	func kubectlIn(p Params, args ...string) string {
556		return "kubectl --context " + p.Context + " -n " + p.Namespace + " " + strings.Join(args, " ")
557	}
