40	// workload says which pods a wait watches and which variables a diagnosis
41	// names. STUB (DEVDESK-540, red phase): only Nexus is described, and nothing
42	// reads it yet.
43	type workload struct {
44		// selector is the label selector of the pods ("key=value").
45		selector string
46		// imageVars are the variables that set the image and its tag.
47		imageVars []string
48		// memoryVars are the variables that size the memory of the pods.
49		memoryVars []string
50	}
51	
52	// nexusWorkload is the Nexus pod.
53	func nexusWorkload() workload {
54		return workload{
55			selector:   podSelector,
56			imageVars:  []string{envImage, envImageTag},
57			memoryVars: []string{envMemoryRequest, envMemoryLimit},
