63	
64	// Deploy applies the manifests of the bench and waits until Nexus answers on a
65	// NodePort. The order is fixed:
66	//
67	//  1. RunPreflight(OpUp): nothing is written before it succeeds
68	//  2. the context is looked at, then the Namespace is applied alone (server-side)
69	//  3. the whole stream of Render(p) is applied, the Namespace again included
70	//  4. a wait polls the pods and the claims of the namespace, diagnoses them
71	//     (PodPending, ImagePull, Crash), then asks the Prober about every host
72	//
73	// It returns as soon as one host answers, with the hosts that answered in that
74	// round; a host that stays mute is a warning on out. The deadline is
75	// Params.Timeout. Every failure is a *BenchError, but a cancelled context, which
76	// is returned as is. Neither the stderr of kubectl nor the error of the prober
77	// reaches a message; the Err of a BenchError keeps the former for errors.Is.
78	func Deploy(ctx context.Context, r Runner, pr Prober, clk Clock, p Params, out io.Writer) (DeployResult, error) {
79		if out == nil {
80			out = io.Discard
81		}
82		pre, err := RunPreflight(ctx, r, p, OpUp)
83		if err != nil {
84			return DeployResult{}, err
85		}
86		// The runner of a test may ignore ctx; the first write must not depend on it.
87		if err := ctx.Err(); err != nil {
88			return DeployResult{}, err
89		}
90		nsDoc, err := RenderNamespace(p)
91		if err != nil {
92			return DeployResult{}, fmt.Errorf("render the Namespace: %w", err)
93		}
94		fullDoc, err := Render(p)
95		if err != nil {
96			return DeployResult{}, fmt.Errorf("render the manifests: %w", err)
97		}
98	
99		d := &deployer{pf: preflight{r: r, p: p}, pr: pr, clk: clk, out: out, hosts: deployHosts(p, pre.NodeIP)}
100		d.say("applying the Namespace %s", p.Namespace)
101		if err := d.apply(ctx, "the Namespace", nsDoc); err != nil {
102			return DeployResult{}, err
103		}
104		d.say("applying the manifests")
105		if err := d.apply(ctx, "the manifests", fullDoc); err != nil {
106			return DeployResult{}, err
107		}
108		reached, err := d.wait(ctx)
109		if err != nil {
110			return DeployResult{}, err
111		}
112		return DeployResult{ReachableHosts: reached, NodeIP: pre.NodeIP}, nil
113	}
114	
115	// deployHosts are the hosts the NodePorts are tried on: Params.Hosts when set,
116	// else the loopback address and the node's InternalIP when there is one.
117	func deployHosts(p Params, nodeIP string) []string {
118		if len(p.Hosts) > 0 {
119			return slices.Clone(p.Hosts)
120		}
121		hosts := []string{loopbackHost}
122		if nodeIP != "" {
123			hosts = append(hosts, nodeIP)
124		}
125		return hosts
126	}
127	
128	// deployer is the state of one Deploy run.
129	type deployer struct {
130		pf    preflight // the runner and the parameters, and its error builders
131		pr    Prober
132		clk   Clock
133		out   io.Writer
134		hosts []string
135	
136		lastSaid     string      // the last state line, so a line is not repeated
137		pendingKey   string      // Cause of the pending reading being timed
138		pendingSince time.Time   // when that reading was first seen
139		candidate    *BenchError // the pending reading of the last round, if any
140	}
141	
142	func (d *deployer) say(format string, args ...any) {
143		_, _ = fmt.Fprintf(d.out, "deploy: "+format+"\n", args...)
144	}
145	
146	// ---- apply ------------------------------------------------------------------
147	
148	// apply sends doc to "kubectl apply --server-side". what names it in messages.
149	func (d *deployer) apply(ctx context.Context, what string, doc []byte) error {
150		args := []string{"apply", "--server-side", "--field-manager=" + fieldManager, "-f", "-", applyTimeout}
151		_, errOut, err := d.pf.r.Run(ctx, doc, args...)
152		if err == nil {
153			return nil
154		}
155		if cerr := ctx.Err(); cerr != nil {
156			return cerr
157		}
158		return d.applyFailure(what, string(errOut), err)
159	}
160	
161	// applyFailure classifies a failed apply from its stderr; the stderr itself is
162	// dropped from the message.
163	func (d *deployer) applyFailure(what, stderr string, err error) *BenchError {
164		p := d.pf.p
165		be := &BenchError{Kind: classifyKubectl(stderr), Err: err}
166		switch be.Kind {
167		case NodePortTaken:
168			be.Cause = "could not apply " + what + ": a NodePort is already allocated"
169			be.Check = d.pf.command("get", "services", "-A", "-o", "json") + ", then set " + envHTTPNodePort + " and " + envDockerNodePort + " to free ports"
170		case AdmissionDenied:
171			be.Cause = "could not apply " + what + ": an admission webhook denied the request"
172			be.Check = d.pf.command("get", "events", "-A", "--sort-by=.lastTimestamp") + ", then read the policy that denied it"
173		case Forbidden:
174			be.Cause = "could not apply " + what + ": the API server refused the request (forbidden)"
175			be.Check = d.pf.command("auth", "can-i", "--list", "-n", p.Namespace)
176		case ClusterUnreachable:
177			be.Cause = "could not apply " + what + ": the cluster did not answer"
178			be.Check = d.pf.command("get", "--raw", "/readyz")
179		default:
180			be.Kind = Unclassified
181			be.Cause = "kubectl failed to apply " + what
182			be.Check = "mise run nexus-bench:render, then " + d.pf.command("apply", "--server-side", "--dry-run=server", "-f", "-")
183		}
184		return be
185	}
186	
187	// ---- the wait ---------------------------------------------------------------
188	
189	// wait polls until a host answers, a diagnosis fails the run, or the deadline
190	// passes. A round reads, diagnoses, then probes; the deadline is looked at after
191	// the round, so the cluster is read once more at the very end.
192	func (d *deployer) wait(ctx context.Context) ([]string, error) {
193		deadline := d.clk.Now().Add(d.pf.p.Timeout)
194		for {
195			obs, err := d.observe(ctx)
196			if err != nil {
197				return nil, err
198			}
199			failure, pending := diagnose(d.pf.p, obs)
200			if failure != nil {
201				return nil, failure
202			}
203			d.candidate = pending
204			if err := d.trackPending(); err != nil {
205				return nil, err
206			}
207			d.report(obs)
208			reached, silent := d.probeHosts(ctx)
209			if err := ctx.Err(); err != nil {
210				return nil, err
211			}
212			if len(reached) > 0 {
213				d.warnSilent(reached, silent)
214				return reached, nil
215			}
216			if !d.clk.Now().Before(deadline) {
217				return nil, d.deadlineError(obs)
218			}
219			if err := d.clk.Sleep(ctx, pollInterval); err != nil {
220				return nil, err
221			}
222		}
223	}
224	
225	// trackPending returns the pending reading of the round once it has lasted for
226	// pendingGrace without a break; a reading that changes or goes away restarts the
227	// count, so a claim that binds when the pod is scheduled is not a failure.
228	func (d *deployer) trackPending() error {
229		if d.candidate == nil {
230			d.pendingKey = ""
231			return nil
232		}
233		if d.candidate.Cause != d.pendingKey {
234			d.pendingKey, d.pendingSince = d.candidate.Cause, d.clk.Now()
235		}
236		if d.clk.Now().Sub(d.pendingSince) >= pendingGrace {
237			return d.candidate
238		}
239		return nil
240	}
241	
242	// deadlineError is the end of a wait that ran out of time. A pending reading
243	// that was still there says more than the deadline does.
244	func (d *deployer) deadlineError(obs observation) error {
245		p := d.pf.p
246		if d.candidate != nil {
247			return d.candidate
248		}
249		return &BenchError{
250			Kind: Deadline,
251			Cause: fmt.Sprintf("Nexus did not answer on NodePort %d (tried %s) within %s; last state: %s",
252				p.HTTPNodePort, strings.Join(d.hosts, ", "), p.Timeout, obs.describe()),
253			Check: describePodCommand(p) + ", then raise " + envTimeout + " if the image pull or the start is only slow; `mise run nexus-bench:down` removes the bench",
254		}
255	}
256	
257	// report prints the state of the cluster when it changed since the last line.
258	func (d *deployer) report(obs observation) {
259		if line := obs.describe(); line != d.lastSaid {
260			d.lastSaid = line
261			d.say("%s", line)
262		}
263	}
264	
265	// probeHosts asks the Prober about every host at once and splits them into the
266	// ones that answered and the ones that did not, each in the order of d.hosts.
267	// The error of the prober is dropped: it names the URL and the cause is enough
268	// in the final message.
269	func (d *deployer) probeHosts(ctx context.Context) (reached, silent []string) {
270		urls := hostURLs(d.hosts, d.pf.p.HTTPNodePort)
271		ok := make([]bool, len(urls))
272		var wg sync.WaitGroup
273		for i, u := range urls {
274			wg.Go(func() { ok[i] = d.pr.Ready(ctx, u) == nil })
275		}
276		wg.Wait()
277		for i, host := range d.hosts {
278			if ok[i] {
279				reached = append(reached, host)
280			} else {
281				silent = append(silent, host)
282			}
283		}
284		return reached, silent
285	}
286	
287	func (d *deployer) warnSilent(reached, silent []string) {
288		for _, host := range silent {
289			d.say("warning: %s did not answer on NodePort %d, although %s did; it will not be listed (check that it is reachable from this machine)",
290				host, d.pf.p.HTTPNodePort, strings.Join(reached, ", "))
291		}
292	}
