127	type scaleCall struct {
128		resource, namespace, replicas string
129	}
130	
131	// upstreamKubectl answers the reads and the scale of the upstream. The cluster
132	// plays before[n] on the n-th round (a round is one sleep) until a scale is
133	// accepted, then after[n] on the n-th round that follows it; the last scripted
134	// round stays for ever.
135	type upstreamKubectl struct {
136		*fakeKubectl
137		clk    *fakeClock
138		before []upstreamRound
139		after  []upstreamRound
140	
141		// The failures a test scripts; each answers its call and has no effect.
142		scaleReply, deploymentReply, podsReply *fakeReply
143	
144		scaledAt int // len(sleeps) when the scale was accepted; -1 before
145		lines    []string
146		writes   []string // every call whose verb writes, normalized
147		scales   []scaleCall
148	}
149	
150	var _ Runner = (*upstreamKubectl)(nil)
151	
152	func newUpstreamKubectl(t *testing.T, p Params, clk *fakeClock, before, after []upstreamRound) *upstreamKubectl {
153		t.Helper()
154		if len(before) == 0 {
155			before = []upstreamRound{cutRound()}
156		}
157		return &upstreamKubectl{fakeKubectl: newFakeKubectl(t, p).ours(), clk: clk, before: before, after: after, scaledAt: -1}
158	}
159	
160	func (u *upstreamKubectl) current() upstreamRound {
161		if u.scaledAt < 0 {
162			return u.before[min(len(u.clk.sleeps), len(u.before)-1)]
163		}
164		if len(u.after) == 0 {
165			u.t.Fatalf("a scale was accepted but no round is scripted after it")
166		}
167		return u.after[min(len(u.clk.sleeps)-u.scaledAt, len(u.after)-1)]
168	}
169	
170	func (u *upstreamKubectl) Run(ctx context.Context, stdin []byte, args ...string) (stdout, stderr []byte, err error) {
171		norm := normalizeArgs(args)
172		joined := strings.Join(norm, " ")
173		u.lines = append(u.lines, joined)
174		verb := verbOf(args)
175		if isWriteVerb(verb) {
176			u.writes = append(u.writes, joined)
177		}
178		switch {
179		case verb == "scale":
180			return u.scale(norm)
181		case isWriteVerb(verb):
182			u.t.Errorf("unexpected write call %q: the upstream is only scaled", args)
183			return nil, []byte("the fake refuses a write: " + verb), errFakeExit1
184		case verb == "get":
185			if g, ok := u.parseGet(norm); ok {
186				return u.answer(g)
187			}
188		}
189		return u.fakeKubectl.Run(ctx, stdin, args...)
190	}
191	
192	type getCall struct {
193		kind, name, namespace, selector, output string
194	}
195	
196	// kindOfResource maps the spellings of kubectl to one name; "" is unknown.
197	func kindOfResource(r string) string {
198		switch r {
199		case "deployment", "deployments", "deploy", "deployment.apps", "deployments.apps":
200			return "deployment"
201		case "pod", "pods", "po":
202			return "pod"
203		case "pvc", "persistentvolumeclaim", "persistentvolumeclaims":
204			return "pvc"
205		}
206		return ""
207	}
208	
209	// parseGet reads "get <resource>[/<name>] [<name>] [flags]"; ok is false for a
210	// resource the fake does not script itself (it goes to the preflight fake).
211	func (u *upstreamKubectl) parseGet(norm []string) (getCall, bool) {
212		var g getCall
213		var positional []string
214		for i := 1; i < len(norm); i++ {
215			switch norm[i] {
216			case "-n", "--namespace":
217				i++
218				g.namespace = at(norm, i)
219			case "-l", "--selector":
220				i++
221				g.selector = at(norm, i)
222			case "-o", "--output":
223				i++
224				g.output = at(norm, i)
225			default:
226				if strings.HasPrefix(norm[i], "-") {
227					return g, false
228				}
229				positional = append(positional, norm[i])
230			}
231		}
232		if len(positional) == 0 {
233			return g, false
234		}
235		resource, name, _ := strings.Cut(positional[0], "/")
236		if g.kind = kindOfResource(resource); g.kind == "" {
237			return g, false
238		}
239		g.name = name
240		if len(positional) > 1 {
241			g.name = positional[1]
242		}
243		if len(positional) > 2 || (len(positional) == 2 && strings.Contains(positional[0], "/")) {
244			u.t.Errorf("unscripted arguments in %q", norm)
245		}
246		if g.namespace != u.p.Namespace {
247			u.t.Errorf("%q reads namespace %q, the run is about %q", norm, g.namespace, u.p.Namespace)
248		}
249		if g.output != "json" {
250			u.t.Errorf("%q must ask for -o json", norm)
251		}
252		return g, true
253	}
254	
255	func notFoundReply(what string) ([]byte, []byte, error) {
256		return nil, []byte("Error from server (NotFound): " + what + " not found\n"), errFakeExit1
257	}
258	
259	func (u *upstreamKubectl) answer(g getCall) ([]byte, []byte, error) {
260		round := u.current()
261		switch g.kind {
262		case "deployment":
263			return u.answerDeployments(g, round)
264		case "pod":
265			return u.answerPods(g, round)
266		}
267		return u.answerClaims(g, round)
268	}
269	
270	func (u *upstreamKubectl) deploymentObject(name string, replicas int, pods []upPod) map[string]any {
271		ready := 0
272		for _, pd := range pods {
273			if pd.ready && !pd.terminating {
274				ready++
275			}
276		}
277		return map[string]any{
278			"metadata": map[string]any{"name": name, "namespace": u.p.Namespace, "labels": map[string]string{"app.kubernetes.io/name": name}},
279			"spec":     map[string]any{"replicas": replicas},
280			"status":   map[string]any{"replicas": len(pods), "readyReplicas": ready, "availableReplicas": ready},
281		}
282	}
283	
284	func (u *upstreamKubectl) answerDeployments(g getCall, round upstreamRound) ([]byte, []byte, error) {
285		if u.deploymentReply != nil {
286			return u.deploymentReply.reply()
287		}
288		if g.name != "" && g.name != upstreamName {
289			u.t.Errorf("get deployment %q: the upstream lifecycle is about %q only", g.name, upstreamName)
290			return notFoundReply("deployments.apps \"" + g.name + "\"")
291		}
292		if g.selector != "" && g.selector != upstreamSelector {
293			u.t.Errorf("get deployment -l %q: not the upstream", g.selector)
294		}
295		if g.name == upstreamName {
296			if !round.deployment {
297				return notFoundReply("deployments.apps \"" + upstreamName + "\"")
298			}
299			return u.mustJSON(u.deploymentObject(upstreamName, round.replicas, round.pods)), nil, nil
300		}
301		// Nexus first: a reader that takes the first item reads the wrong one.
302		items := []any{u.deploymentObject("nexus", 1, nil)}
303		if round.deployment {
304			items = append(items, u.deploymentObject(upstreamName, round.replicas, round.pods))
305		}
306		return u.mustJSON(map[string]any{"apiVersion": "v1", "kind": "List", "items": items}), nil, nil
307	}
308	
309	func (u *upstreamKubectl) answerPods(g getCall, round upstreamRound) ([]byte, []byte, error) {
310		if u.podsReply != nil {
311			return u.podsReply.reply()
312		}
313		if g.selector != upstreamSelector {
314			u.t.Errorf("get pods selects %q, want %q", g.selector, upstreamSelector)
315		}
316		items := []any{}
317		for _, pd := range round.pods {
318			items = append(items, pd.object())
319		}
320		return u.mustJSON(map[string]any{"apiVersion": "v1", "kind": "List", "items": items}), nil, nil
321	}
322	
323	func (u *upstreamKubectl) claimObject(name, app, phase string) map[string]any {
324		return map[string]any{
325			"metadata": map[string]any{"name": name, "labels": map[string]string{"app.kubernetes.io/name": app}},
326			"status":   map[string]any{"phase": phase},
327		}
328	}
329	
330	func (u *upstreamKubectl) answerClaims(g getCall, round upstreamRound) ([]byte, []byte, error) {
331		nexusPhase := round.nexusClaim
332		if nexusPhase == "" {
333			nexusPhase = "Bound"
334		}
335		// Nexus first, against the order of kubectl: the reader must pick by name.
336		claims := []map[string]any{u.claimObject(deployPVCName, "nexus", nexusPhase)}
337		if round.claim != "" {
338			claims = append(claims, u.claimObject(upstreamClaim, upstreamName, round.claim))
339		}
340		var items []any
341		for _, c := range claims {
342			name := c["metadata"].(map[string]any)["name"]
343			app := c["metadata"].(map[string]any)["labels"].(map[string]string)["app.kubernetes.io/name"]
344			if g.name != "" && g.name != name {
345				continue
346			}
347			if g.selector != "" && g.selector != "app.kubernetes.io/name="+app {
348				continue
349			}
350			items = append(items, c)
351		}
352		if g.name != "" {
353			if len(items) == 0 {
354				return notFoundReply("persistentvolumeclaims \"" + g.name + "\"")
355			}
356			return u.mustJSON(items[0]), nil, nil
357		}
358		if items == nil {
359			items = []any{}
360		}
361		return u.mustJSON(map[string]any{"apiVersion": "v1", "kind": "List", "items": items}), nil, nil
362	}
363	
364	// scale reads "scale deployment/bench-upstream --replicas=N -n <ns>".
365	func (u *upstreamKubectl) scale(norm []string) ([]byte, []byte, error) {
366		var call scaleCall
367		var positional []string
368		for i := 1; i < len(norm); i++ {
369			switch a := norm[i]; {
370			case a == "-n" || a == "--namespace":
371				i++
372				call.namespace = at(norm, i)
373			case strings.HasPrefix(a, "--replicas="):
374				call.replicas = strings.TrimPrefix(a, "--replicas=")
375			case strings.HasPrefix(a, "--timeout=") || strings.HasPrefix(a, "--current-replicas="):
376			case strings.HasPrefix(a, "-"):
377				u.t.Errorf("unscripted argument %q in %q", a, norm)
378			default:
379				positional = append(positional, a)
380			}
381		}
382		call.resource = strings.Join(positional, "/")
383		u.scales = append(u.scales, call)
384		if call.resource != "deployment/"+upstreamName && call.resource != "deployments/"+upstreamName && call.resource != "deploy/"+upstreamName {
385			u.t.Errorf("scale targets %q, want deployment/%s: the upstream is the only thing to scale", call.resource, upstreamName)
386			return nil, []byte("the fake refuses this scale"), errFakeExit1
387		}
388		if call.namespace != u.p.Namespace {
389			u.t.Errorf("scale in namespace %q, the run is about %q", call.namespace, u.p.Namespace)
390		}
391		if u.scaleReply != nil {
392			return u.scaleReply.reply()
393		}
394		if call.replicas == "" {
395			u.t.Errorf("scale without --replicas: %q", norm)
396		}
397		u.scaledAt = len(u.clk.sleeps)
398		return []byte("deployment.apps/" + upstreamName + " scaled\n"), nil, nil
399	}
400	
401	// requireNoPreflight checks the call set holds no question of the preflight.
402	func (u *upstreamKubectl) requireNoPreflight() {
403		u.t.Helper()
404		for _, line := range u.lines {
405			for _, banned := range []string{"auth ", "config ", "get namespace", "get nodes", "get services", "get --raw"} {
406				if strings.HasPrefix(line, banned) {
407					u.t.Errorf("call %q belongs to the preflight, which the caller runs", line)
408				}
409			}
410		}
411	}
