529			{"one replica, container being created", roundOf(1, creatingPod()), UpstreamStarting},
530			{"one replica, container running but not ready", roundOf(1, startingPod()), UpstreamStarting},
531			{"one replica, image pull failing is starting, not an error", roundOf(1, pullFailedPod("ImagePullBackOff")), UpstreamStarting},
