11	// Op is what a run of the bench is about to do; it decides which checks the
12	// preflight makes.
13	type Op int
14	
15	const (
16		OpUp Op = iota
17		OpProvision
18		OpDown
19		OpStatus
20		// OpSeed is appended after OpStatus: no earlier value moves.
21		OpSeed
22	)
23	
24	// PreflightResult is what a successful preflight learned about the cluster.
25	type PreflightResult struct {
26		// NamespaceExists is true when the bench namespace is there.
27		NamespaceExists bool
28		// NamespaceOurs is true when it carries our managed-by label.
29		NamespaceOurs bool
30		// NodeIP is the InternalIP of the first node that reports one; empty when
31		// none does, which is not an error (the other hosts still work). It is not
32		// read for OpDown.
33		NodeIP string
34	}
35	
36	const (
37		// managedByLabel and managedByValue are the label 00-namespace.yaml.tmpl
38		// puts on the namespace; down deletes a namespace only when it carries it.
39		managedByLabel = "app.kubernetes.io/managed-by"
40		managedByValue = "devdesk-nexus-bench"
41	
42		// nexusServiceName is the Service 30-service.yaml.tmpl creates.
43		nexusServiceName = "nexus"
44	
45		// requestTimeout bounds every call that reaches the API server.
46		requestTimeout = "--request-timeout=10s"
47	)
48	
49	// permissionScope says where a can-i question applies.
50	type permissionScope int
51	
52	const (
53		scopeCluster   permissionScope = iota // no flag: cluster-scoped resources
54		scopeNamespace                        // -n <namespace>
55		scopeAll                              // -A
56	)
57	
58	// permission is one "kubectl auth can-i" question the preflight asks.
59	type permission struct {
60		verb, resource string
61		scope          permissionScope
62	}
63	
64	// permissionsByOp is the list F2 of the plan: what each operation needs. An
65	// operation absent from the map (status) writes nothing and asks nothing.
66	var permissionsByOp = map[Op][]permission{
67		OpUp: {
68			{"create", "namespaces", scopeCluster},
69			{"create", "persistentvolumeclaims", scopeNamespace},
70			{"create", "services", scopeNamespace},
71			{"create", "deployments", scopeNamespace},
72			{"create", "pods/exec", scopeNamespace},
73			{"list", "services", scopeAll},
74			// Server-side apply is a PATCH, also on a second run (the namespace
75			// included), and Deploy reads the pods and the claims of the namespace
76			// while it waits.
77			{"patch", "namespaces", scopeCluster},
78			{"patch", "deployments", scopeNamespace},
79			{"patch", "services", scopeNamespace},
80			{"patch", "persistentvolumeclaims", scopeNamespace},
81			{"get", "pods", scopeNamespace},
82			{"list", "pods", scopeNamespace},
83			{"get", "persistentvolumeclaims", scopeNamespace},
84			{"list", "persistentvolumeclaims", scopeNamespace},
85		},
86		// Provision waits for the Deployment and reads the pods before it execs.
87		OpProvision: {
88			{"create", "pods/exec", scopeNamespace},
89			{"get", "deployments", scopeNamespace},
90			{"list", "pods", scopeNamespace},
91		},
92		OpDown: {{"delete", "namespaces", scopeCluster}},
93	}
94	
95	// RunPreflight checks, with read-only kubectl calls, that op can go ahead, and
96	// returns what it learned. Nothing is written to the cluster, whatever the
97	// outcome: a failure here means no write was ever issued. The checks run in a
98	// fixed order and stop at the first failure, so nothing is asked of a cluster
99	// the context does not reach:
100	//
101	//  1. the parameters (no call at all)
102	//  2. the context is in the kubeconfig
103	//  3. the API server answers /readyz
104	//  4. the can-i questions of the operation
105	//  5. the namespace: absent, ours, or foreign
106	//  6. up only: no other Service holds one of our NodePorts
107	//  7. all but down: the InternalIP of the node
108	//
109	// Every failure is a *BenchError.
110	func RunPreflight(ctx context.Context, r Runner, p Params, op Op) (PreflightResult, error) {
111		var res PreflightResult
112		if err := p.Validate(); err != nil {
113			return res, err
114		}
115		pf := preflight{r: r, p: p}
116		if err := pf.checkContext(ctx); err != nil {
117			return res, err
118		}
119		if err := pf.checkReachable(ctx); err != nil {
120			return res, err
121		}
122		for _, perm := range permissionsByOp[op] {
123			if err := pf.checkPermission(ctx, perm); err != nil {
124				return res, err
125			}
126		}
127		res, err := pf.checkNamespace(ctx, op)
128		if err != nil {
129			return res, err
130		}
131		if op == OpUp {
132			if err := pf.checkNodePorts(ctx); err != nil {
133				return res, err
134			}
135		}
136		if op != OpDown {
137			if res.NodeIP, err = pf.nodeIP(ctx); err != nil {
138				return res, err
139			}
140		}
141		return res, nil
142	}
