144	type preflight struct {
145		r Runner
146		p Params
147	}
148	
149	// local runs a call that does not reach the API server.
150	func (pf preflight) local(ctx context.Context, args ...string) (stdout, stderr string, err error) {
151		out, errOut, err := pf.r.Run(ctx, nil, args...)
152		return string(out), string(errOut), err
153	}
154	
155	// remote runs a call that reaches the API server, under a request timeout.
156	func (pf preflight) remote(ctx context.Context, args ...string) (stdout, stderr string, err error) {
157		return pf.local(ctx, slices.Concat(args, []string{requestTimeout})...)
158	}
159	
160	// command is the kubectl command line a user can run to repeat a call.
161	func (pf preflight) command(args ...string) string {
162		return "kubectl --context " + pf.p.Context + " " + strings.Join(args, " ")
163	}
164	
165	// failure turns a failed kubectl call into a BenchError whose kind comes from
166	// the stderr. Neither the stderr nor the sub-process error reaches the message.
167	func (pf preflight) failure(what string, args []string, stderr string, err error) *BenchError {
168		kind := classifyKubectl(stderr)
169		reason := "kubectl failed"
170		switch kind {
171		case Forbidden:
172			reason = "the API server refused the request (forbidden)"
173		case ClusterUnreachable:
174			reason = "the cluster did not answer"
175		}
176		return &BenchError{
177			Kind:  kind,
178			Cause: "could not " + what + ": " + reason,
179			Check: pf.command(args...),
180			Err:   err,
181		}
182	}
183	
184	func (pf preflight) checkContext(ctx context.Context) error {
185		args := []string{"config", "get-contexts", "-o", "name"}
186		out, errOut, err := pf.local(ctx, args...)
187		if err != nil {
188			return pf.failure("list the kubeconfig contexts", args, errOut, err)
189		}
190		for _, line := range strings.Split(out, "\n") {
191			if strings.TrimSpace(line) == pf.p.Context {
192				return nil
193			}
194		}
195		return &BenchError{
196			Kind:  ContextNotFound,
197			Cause: fmt.Sprintf("no kubeconfig context is named %q", pf.p.Context),
198			Check: "kubectl config get-contexts -o name, then set NEXUS_BENCH_CONTEXT to one of them",
199		}
200	}
201	
202	func (pf preflight) checkReachable(ctx context.Context) error {
203		args := []string{"get", "--raw", "/readyz"}
204		_, errOut, err := pf.remote(ctx, args...)
205		if err == nil {
206			return nil
207		}
208		// A refusal (an expired token, a 403) is not an absent cluster: say so.
209		// Anything else, classified or not, means the server did not answer.
210		if classifyKubectl(errOut) == Forbidden {
211			return pf.failure("reach the API server", args, errOut, err)
212		}
213		return &BenchError{
214			Kind:  ClusterUnreachable,
215			Cause: fmt.Sprintf("the API server of context %q does not answer /readyz", pf.p.Context),
216			Check: pf.command(args...),
217			Err:   err,
218		}
219	}
