221	// checkPermission asks "kubectl auth can-i". A "no" arrives on stdout with a
222	// non-zero exit, so the answer is read before the error.
223	func (pf preflight) checkPermission(ctx context.Context, perm permission) error {
224		args := []string{"auth", "can-i", perm.verb, perm.resource}
225		where := "cluster-wide"
226		switch perm.scope {
227		case scopeNamespace:
228			args = append(args, "-n", pf.p.Namespace)
229			where = fmt.Sprintf("in namespace %q", pf.p.Namespace)
230		case scopeAll:
231			args = append(args, "-A")
232			where = "in all namespaces"
233		}
234		out, errOut, err := pf.remote(ctx, args...)
235		answer := strings.TrimSpace(out)
236		switch {
237		case strings.HasPrefix(answer, "no"):
238			return &BenchError{
239				Kind:  Forbidden,
240				Cause: fmt.Sprintf("the current user is not allowed to %s %s %s", perm.verb, perm.resource, where),
241				Check: pf.command(args...),
242				Err:   err,
243			}
244		case err == nil && strings.HasPrefix(answer, "yes"):
245			return nil
246		}
247		return pf.failure(fmt.Sprintf("check the permission to %s %s", perm.verb, perm.resource), args, errOut, err)
248	}
