250	// namespaceObject is the part of a Namespace the preflight reads.
251	type namespaceObject struct {
252		Metadata struct {
253			Labels map[string]string `json:"labels"`
254		} `json:"metadata"`
255	}
256	
257	func (pf preflight) checkNamespace(ctx context.Context, op Op) (PreflightResult, error) {
258		var res PreflightResult
259		ns := pf.p.Namespace
260		args := []string{"get", "namespace", ns, "-o", "json"}
261		out, errOut, err := pf.remote(ctx, args...)
262		switch {
263		case err != nil && isNotFound(errOut):
264			// Absent: only provision and status need it.
265			if op == OpProvision || op == OpStatus {
266				return res, &BenchError{
267					Kind:  NamespaceMissing,
268					Cause: fmt.Sprintf("namespace %q does not exist", ns),
269					Check: pf.command(args[:3]...) + ", then run `mise run nexus-bench:up`",
270					Err:   err,
271				}
272			}
273			return res, nil
274		case err != nil:
275			return res, pf.failure(fmt.Sprintf("read the namespace %q", ns), args, errOut, err)
276		}
277	
278		var obj namespaceObject
279		if err := json.Unmarshal([]byte(out), &obj); err != nil {
280			return res, &BenchError{
281				Kind:  Unclassified,
282				Cause: fmt.Sprintf("kubectl answered with something that is not a Namespace for %q", ns),
283				Check: pf.command(args...),
284				Err:   err,
285			}
286		}
287		res.NamespaceExists = true
288		res.NamespaceOurs = obj.Metadata.Labels[managedByLabel] == managedByValue
289		if !res.NamespaceOurs {
290			return res, &BenchError{
291				Kind:  NamespaceForeign,
292				Cause: fmt.Sprintf("namespace %q exists but does not carry the label %s=%s, so the bench did not create it", ns, managedByLabel, managedByValue),
293				Check: pf.command("get", "namespace", ns, "--show-labels") + ", or choose another NEXUS_BENCH_NAMESPACE",
294			}
295		}
296		return res, nil
297	}
