299	// serviceList is the part of a Service list the preflight reads.
300	type serviceList struct {
301		Items []struct {
302			Metadata struct {
303				Name      string `json:"name"`
304				Namespace string `json:"namespace"`
305			} `json:"metadata"`
306			Spec struct {
307				Ports []struct {
308					NodePort int `json:"nodePort"`
309				} `json:"ports"`
310			} `json:"spec"`
311		} `json:"items"`
