314	// checkNodePorts reads every Service of the cluster: the list of taken
315	// NodePorts is not a constant (F1). Our own Service, in our namespace, may hold
316	// them: that is a second up.
317	func (pf preflight) checkNodePorts(ctx context.Context) error {
318		args := []string{"get", "services", "-A", "-o", "json"}
319		out, errOut, err := pf.remote(ctx, args...)
320		if err != nil {
321			return pf.failure("list the Services of the cluster", args, errOut, err)
322		}
323		var list serviceList
324		if err := json.Unmarshal([]byte(out), &list); err != nil {
325			return &BenchError{
326				Kind:  Unclassified,
327				Cause: "kubectl answered with something that is not a Service list",
328				Check: pf.command(args...),
329				Err:   err,
330			}
331		}
332		var taken []string
333		for _, svc := range list.Items {
334			if svc.Metadata.Namespace == pf.p.Namespace && svc.Metadata.Name == nexusServiceName {
335				continue
336			}
337			for _, port := range svc.Spec.Ports {
338				if port.NodePort == pf.p.HTTPNodePort || port.NodePort == pf.p.DockerNodePort {
339					taken = append(taken, fmt.Sprintf("%d is held by Service %s/%s", port.NodePort, svc.Metadata.Namespace, svc.Metadata.Name))
340				}
341			}
342		}
343		if len(taken) > 0 {
344			return &BenchError{
345				Kind:  NodePortTaken,
346				Cause: "NodePort " + strings.Join(taken, ", "),
347				Check: pf.command(args...) + ", then set NEXUS_BENCH_HTTP_NODEPORT and NEXUS_BENCH_DOCKER_NODEPORT to free ports",
348			}
349		}
350		return nil
351	}
