131	// upstreamKubectl answers the reads and the scale of the upstream. The cluster
132	// plays before[n] on the n-th round (a round is one sleep) until a scale is
133	// accepted, then after[n] on the n-th round that follows it; the last scripted
134	// round stays for ever.
135	type upstreamKubectl struct {
136		*fakeKubectl
137		clk    *fakeClock
138		before []upstreamRound
139		after  []upstreamRound
140	
141		// The failures a test scripts; each answers its call and has no effect.
142		scaleReply, deploymentReply, podsReply *fakeReply
143	
144		scaledAt int // len(sleeps) when the scale was accepted; -1 before
145		lines    []string
146		writes   []string // every call whose verb writes, normalized
147		scales   []scaleCall
148	}
149	
150	var _ Runner = (*upstreamKubectl)(nil)
151	
152	func newUpstreamKubectl(t *testing.T, p Params, clk *fakeClock, before, after []upstreamRound) *upstreamKubectl {
153		t.Helper()
154		if len(before) == 0 {
155			before = []upstreamRound{cutRound()}
156		}
157		return &upstreamKubectl{fakeKubectl: newFakeKubectl(t, p).ours(), clk: clk, before: before, after: after, scaledAt: -1}
158	}
159	
160	func (u *upstreamKubectl) current() upstreamRound {
161		if u.scaledAt < 0 {
162			return u.before[min(len(u.clk.sleeps), len(u.before)-1)]
163		}
164		if len(u.after) == 0 {
165			u.t.Fatalf("a scale was accepted but no round is scripted after it")
166		}
167		return u.after[min(len(u.clk.sleeps)-u.scaledAt, len(u.after)-1)]
168	}
