259	func (u *upstreamKubectl) answer(g getCall) ([]byte, []byte, error) {
260		round := u.current()
261		switch g.kind {
262		case "deployment":
263			return u.answerDeployments(g, round)
264		case "pod":
265			return u.answerPods(g, round)
266		}
267		return u.answerClaims(g, round)
268	}
