1000	// twoClaims answers the claim list of Deploy the way the namespace looks once the
1001	// upstream manifests are applied: the claim of the upstream, which kubectl lists
1002	// first (by name), then the claim of Nexus.
1003	type twoClaims struct {
1004		*deployKubectl
1005		upstreamPhase string
1006	}
1007	
1008	func (c twoClaims) Run(ctx context.Context, stdin []byte, args ...string) ([]byte, []byte, error) {
1009		out, errOut, err := c.deployKubectl.Run(ctx, stdin, args...)
1010		norm := normalizeArgs(args)
1011		if err != nil || verbOf(args) != "get" || len(norm) < 2 || !isPVCResource(norm[1]) {
1012			return out, errOut, err
1013		}
1014		var list struct {
1015			Items []any `json:"items"`
1016		}
1017		if jerr := json.Unmarshal(out, &list); jerr != nil {
1018			c.t.Fatalf("decoding the claim list: %v", jerr)
1019		}
1020		upstream := map[string]any{
1021			"metadata": map[string]any{"name": upstreamClaim, "labels": map[string]string{"app.kubernetes.io/name": upstreamName}},
1022			"status":   map[string]any{"phase": c.upstreamPhase},
1023		}
1024		list.Items = append([]any{upstream}, list.Items...)
1025		return c.mustJSON(map[string]any{"apiVersion": "v1", "kind": "List", "items": list.Items}), errOut, nil
1026	}
