1037			}
1038			if !slices.Contains(res.ReachableHosts, "127.0.0.1") {
1039				t.Errorf("ReachableHosts = %q", res.ReachableHosts)
1040			}
1041		})
1042		t.Run("a Pending claim of Nexus is still reported although the upstream's is Bound", func(t *testing.T) {
1043			stuck := repeatStates(state("Pending", startingPod()), 3)
1044			e := newDeployEnv(t, deployParams(), nil, stuck...)
1045			_, err := Deploy(context.Background(), twoClaims{e.kube, "Bound"}, e.pr, e.clk, e.p, &e.out)
