11	// The preflight of the seed and the two permissions `up` gains (DEVDESK-505,
12	// NX-02a, step 5). Against the scripted kubectl of preflight_test.go, which
13	// records every "auth can-i" question in order.
14	//
15	// Choices of the tests, to settle with the code:
16	//   - OpSeed is appended after OpStatus; no earlier value moves.
17	//   - The questions of seed, in this order, all in the bench namespace:
18	//     get deployments, list pods, create pods/portforward, patch
19	//     deployments/scale (the last one is EnsureUpstream's).
20	//   - up keeps its fourteen questions where they are and asks the two new ones
21	//     after them: patch deployments/scale, then create pods/portforward.
22	//   - seed refuses an absent or a foreign namespace, like provision and status,
23	//     and does not read the Services of the cluster (that is up's NodePort
24	//     check); it reads the node address like provision.
25	//   - A refused question ends the preflight there: the later ones are not asked.
26	//   - Nothing is ever written.
27	
28	// asked renders the can-i questions the fake saw: "verb resource", plus "-n <ns>"
29	// or "-A" when the question was scoped.
30	func asked(f *fakeKubectl) []string {
31		out := make([]string, 0, len(f.asked))
32		for _, q := range f.asked {
33			s := q.verb + " " + q.resource
34			switch {
35			case q.allNamespaces:
36				s += " -A"
37			case q.namespace != "":
38				s += " -n " + q.namespace
39			}
40			out = append(out, s)
41		}
42		return out
43	}
