2	
3	import (
4		"context"
5		"encoding/json"
6		"fmt"
7		"slices"
8		"strings"
9	)
10	
11	// Op is what a run of the bench is about to do; it decides which checks the
12	// preflight makes.
13	type Op int
14	
15	const (
16		OpUp Op = iota
17		OpProvision
18		OpDown
19		OpStatus
20		// OpSeed is appended after OpStatus: no earlier value moves.
21		OpSeed
22	)
23	
24	// PreflightResult is what a successful preflight learned about the cluster.
25	type PreflightResult struct {
26		// NamespaceExists is true when the bench namespace is there.
27		NamespaceExists bool
28		// NamespaceOurs is true when it carries our managed-by label.
29		NamespaceOurs bool
30		// NodeIP is the InternalIP of the first node that reports one; empty when
31		// none does, which is not an error (the other hosts still work). It is not
32		// read for OpDown.
33		NodeIP string
34	}
35	
36	const (
37		// managedByLabel and managedByValue are the label 00-namespace.yaml.tmpl
38		// puts on the namespace; down deletes a namespace only when it carries it.
39		managedByLabel = "app.kubernetes.io/managed-by"
40		managedByValue = "devdesk-nexus-bench"
41	
42		// nexusServiceName is the Service 30-service.yaml.tmpl creates.
43		nexusServiceName = "nexus"
44	
45		// requestTimeout bounds every call that reaches the API server.
46		requestTimeout = "--request-timeout=10s"
47	)
48	
49	// permissionScope says where a can-i question applies.
50	type permissionScope int
51	
52	const (
53		scopeCluster   permissionScope = iota // no flag: cluster-scoped resources
54		scopeNamespace                        // -n <namespace>
55		scopeAll                              // -A
56	)
57	
58	// permission is one "kubectl auth can-i" question the preflight asks.
59	type permission struct {
60		verb, resource string
61		scope          permissionScope
62	}
63	
64	// permissionsByOp is the list F2 of the plan: what each operation needs. An
65	// operation absent from the map (status) writes nothing and asks nothing.
66	var permissionsByOp = map[Op][]permission{
67		OpUp: {
68			{"create", "namespaces", scopeCluster},
69			{"create", "persistentvolumeclaims", scopeNamespace},
70			{"create", "services", scopeNamespace},
71			{"create", "deployments", scopeNamespace},
72			{"create", "pods/exec", scopeNamespace},
73			{"list", "services", scopeAll},
74			// Server-side apply is a PATCH, also on a second run (the namespace
75			// included), and Deploy reads the pods and the claims of the namespace
76			// while it waits.
77			{"patch", "namespaces", scopeCluster},
78			{"patch", "deployments", scopeNamespace},
79			{"patch", "services", scopeNamespace},
80			{"patch", "persistentvolumeclaims", scopeNamespace},
81			{"get", "pods", scopeNamespace},
82			{"list", "pods", scopeNamespace},
83			{"get", "persistentvolumeclaims", scopeNamespace},
84			{"list", "persistentvolumeclaims", scopeNamespace},
85		},
86		// Provision waits for the Deployment and reads the pods before it execs.
87		OpProvision: {
88			{"create", "pods/exec", scopeNamespace},
89			{"get", "deployments", scopeNamespace},
90			{"list", "pods", scopeNamespace},
91		},
92		OpDown: {{"delete", "namespaces", scopeCluster}},
93	}
94	
95	// RunPreflight checks, with read-only kubectl calls, that op can go ahead, and
96	// returns what it learned. Nothing is written to the cluster, whatever the
97	// outcome: a failure here means no write was ever issued. The checks run in a
98	// fixed order and stop at the first failure, so nothing is asked of a cluster
99	// the context does not reach:
100	//
101	//  1. the parameters (no call at all)
102	//  2. the context is in the kubeconfig
103	//  3. the API server answers /readyz
104	//  4. the can-i questions of the operation
105	//  5. the namespace: absent, ours, or foreign
106	//  6. up only: no other Service holds one of our NodePorts
107	//  7. all but down: the InternalIP of the node
108	//
109	// Every failure is a *BenchError.
110	func RunPreflight(ctx context.Context, r Runner, p Params, op Op) (PreflightResult, error) {
111		var res PreflightResult
112		if err := p.Validate(); err != nil {
113			return res, err
114		}
115		pf := preflight{r: r, p: p}
116		if err := pf.checkContext(ctx); err != nil {
117			return res, err
118		}
119		if err := pf.checkReachable(ctx); err != nil {
120			return res, err
121		}
122		for _, perm := range permissionsByOp[op] {
123			if err := pf.checkPermission(ctx, perm); err != nil {
124				return res, err
125			}
126		}
127		res, err := pf.checkNamespace(ctx, op)
128		if err != nil {
129			return res, err
130		}
131		if op == OpUp {
132			if err := pf.checkNodePorts(ctx); err != nil {
133				return res, err
134			}
135		}
136		if op != OpDown {
137			if res.NodeIP, err = pf.nodeIP(ctx); err != nil {
138				return res, err
139			}
140		}
141		return res, nil
142	}
143	
144	type preflight struct {
145		r Runner
146		p Params
147	}
148	
149	// local runs a call that does not reach the API server.
150	func (pf preflight) local(ctx context.Context, args ...string) (stdout, stderr string, err error) {
151		out, errOut, err := pf.r.Run(ctx, nil, args...)
152		return string(out), string(errOut), err
153	}
154	
155	// remote runs a call that reaches the API server, under a request timeout.
156	func (pf preflight) remote(ctx context.Context, args ...string) (stdout, stderr string, err error) {
157		return pf.local(ctx, slices.Concat(args, []string{requestTimeout})...)
158	}
159	
160	// command is the kubectl command line a user can run to repeat a call.
161	func (pf preflight) command(args ...string) string {
162		return "kubectl --context " + pf.p.Context + " " + strings.Join(args, " ")
163	}
164	
165	// failure turns a failed kubectl call into a BenchError whose kind comes from
166	// the stderr. Neither the stderr nor the sub-process error reaches the message.
167	func (pf preflight) failure(what string, args []string, stderr string, err error) *BenchError {
168		kind := classifyKubectl(stderr)
169		reason := "kubectl failed"
170		switch kind {
171		case Forbidden:
172			reason = "the API server refused the request (forbidden)"
173		case ClusterUnreachable:
174			reason = "the cluster did not answer"
175		}
176		return &BenchError{
177			Kind:  kind,
178			Cause: "could not " + what + ": " + reason,
179			Check: pf.command(args...),
180			Err:   err,
181		}
182	}
183	
184	func (pf preflight) checkContext(ctx context.Context) error {
185		args := []string{"config", "get-contexts", "-o", "name"}
186		out, errOut, err := pf.local(ctx, args...)
187		if err != nil {
188			return pf.failure("list the kubeconfig contexts", args, errOut, err)
189		}
190		for _, line := range strings.Split(out, "\n") {
191			if strings.TrimSpace(line) == pf.p.Context {
192				return nil
193			}
194		}
195		return &BenchError{
196			Kind:  ContextNotFound,
197			Cause: fmt.Sprintf("no kubeconfig context is named %q", pf.p.Context),
198			Check: "kubectl config get-contexts -o name, then set NEXUS_BENCH_CONTEXT to one of them",
199		}
200	}
201	
202	func (pf preflight) checkReachable(ctx context.Context) error {
203		args := []string{"get", "--raw", "/readyz"}
204		_, errOut, err := pf.remote(ctx, args...)
205		if err == nil {
206			return nil
207		}
208		// A refusal (an expired token, a 403) is not an absent cluster: say so.
209		// Anything else, classified or not, means the server did not answer.
210		if classifyKubectl(errOut) == Forbidden {
211			return pf.failure("reach the API server", args, errOut, err)
212		}
213		return &BenchError{
214			Kind:  ClusterUnreachable,
215			Cause: fmt.Sprintf("the API server of context %q does not answer /readyz", pf.p.Context),
216			Check: pf.command(args...),
217			Err:   err,
218		}
219	}
220	
221	// checkPermission asks "kubectl auth can-i". A "no" arrives on stdout with a
222	// non-zero exit, so the answer is read before the error.
223	func (pf preflight) checkPermission(ctx context.Context, perm permission) error {
224		args := []string{"auth", "can-i", perm.verb, perm.resource}
225		where := "cluster-wide"
226		switch perm.scope {
227		case scopeNamespace:
228			args = append(args, "-n", pf.p.Namespace)
229			where = fmt.Sprintf("in namespace %q", pf.p.Namespace)
230		case scopeAll:
231			args = append(args, "-A")
232			where = "in all namespaces"
233		}
234		out, errOut, err := pf.remote(ctx, args...)
235		answer := strings.TrimSpace(out)
236		switch {
237		case strings.HasPrefix(answer, "no"):
238			return &BenchError{
239				Kind:  Forbidden,
240				Cause: fmt.Sprintf("the current user is not allowed to %s %s %s", perm.verb, perm.resource, where),
241				Check: pf.command(args...),
242				Err:   err,
243			}
244		case err == nil && strings.HasPrefix(answer, "yes"):
245			return nil
246		}
247		return pf.failure(fmt.Sprintf("check the permission to %s %s", perm.verb, perm.resource), args, errOut, err)
248	}
249	
250	// namespaceObject is the part of a Namespace the preflight reads.
251	type namespaceObject struct {
252		Metadata struct {
253			Labels map[string]string `json:"labels"`
254		} `json:"metadata"`
255	}
256	
257	func (pf preflight) checkNamespace(ctx context.Context, op Op) (PreflightResult, error) {
258		var res PreflightResult
259		ns := pf.p.Namespace
260		args := []string{"get", "namespace", ns, "-o", "json"}
261		out, errOut, err := pf.remote(ctx, args...)
262		switch {
263		case err != nil && isNotFound(errOut):
264			// Absent: only provision and status need it.
265			if op == OpProvision || op == OpStatus {
266				return res, &BenchError{
267					Kind:  NamespaceMissing,
268					Cause: fmt.Sprintf("namespace %q does not exist", ns),
269					Check: pf.command(args[:3]...) + ", then run `mise run nexus-bench:up`",
270					Err:   err,
271				}
272			}
273			return res, nil
274		case err != nil:
275			return res, pf.failure(fmt.Sprintf("read the namespace %q", ns), args, errOut, err)
276		}
277	
278		var obj namespaceObject
279		if err := json.Unmarshal([]byte(out), &obj); err != nil {
280			return res, &BenchError{
281				Kind:  Unclassified,
