365	// nodeIP returns the first InternalIP any node reports, or "" when none does.
366	func (pf preflight) nodeIP(ctx context.Context) (string, error) {
367		args := []string{"get", "nodes", "-o", "json"}
368		out, errOut, err := pf.remote(ctx, args...)
369		if err != nil {
370			return "", pf.failure("read the nodes", args, errOut, err)
371		}
372		var nodes nodeList
373		if err := json.Unmarshal([]byte(out), &nodes); err != nil {
374			return "", &BenchError{
375				Kind:  Unclassified,
376				Cause: "kubectl answered with something that is not a Node list",
377				Check: pf.command(args...),
378				Err:   err,
379			}
380		}
381		for _, node := range nodes.Items {
382			for _, addr := range node.Status.Addresses {
383				if addr.Type == "InternalIP" {
384					return addr.Address, nil
385				}
386			}
387		}
388		return "", nil
389	}
